-- 1 bis. Axes du programme -------------------------------------------------
-- `chapters.theme` (migration 234) : l’intitulé du programme officiel qui
-- coiffe le chapitre. La page matière s’en sert pour grouper au lieu
-- d’aligner 28 lignes à plat. UPDATE et non INSERT : le chapitre peut déjà
-- exister (l’INSERT précédent l’aurait alors ignoré).
UPDATE public.chapters c SET theme = v.theme
  FROM (VALUES
    ('53b26f6c-f960-5e34-adc7-f3714b4fff47'::uuid, 'Au cœur de l’ordinateur'),
    ('c45be451-72c7-5d73-94fc-42ec8abb49c8'::uuid, 'Au cœur de l’ordinateur'),
    ('09fa54a0-678b-50c8-86bc-1bdfcea63801'::uuid, 'Au cœur de l’ordinateur'),
    ('6b3a41d5-4016-5a4b-b56d-734107f3058d'::uuid, 'Au cœur de l’ordinateur'),
    ('2015778f-3989-5198-836a-def00516e7a2'::uuid, 'L’ordinateur de bureau'),
    ('26f0630d-db73-52ed-9c92-e3b79c2cb577'::uuid, 'L’ordinateur de bureau'),
    ('944fa77d-2abd-5a1a-b241-8ceafcb4358c'::uuid, 'Réseaux'),
    ('f56d2923-9ba1-592d-99f2-0670d90b4753'::uuid, 'Réseaux'),
    ('1b0944ea-299a-57f2-acd4-2e2058b22b24'::uuid, 'Interagir sur le web'),
    ('10f1cbac-9c1d-59a3-abe7-410bcc60f1f1'::uuid, 'Interagir sur le web'),
    ('965c559d-8bd5-5f73-a3cb-59a0455f32cb'::uuid, 'Génie logiciel'),
    ('7e6aa87d-1ac7-564a-8ef8-ec1d8972ed26'::uuid, 'Génie logiciel'),
    ('d620b0be-1101-520a-a905-833c6cc1550c'::uuid, 'Génie logiciel'),
    ('d0a2f8ab-6328-54f5-97e2-25eadf056950'::uuid, 'Algorithmique et programmation'),
    ('13f5235a-023e-5e5c-bae2-375e0aad9ae8'::uuid, 'Algorithmique et programmation'),
    ('c24b6cea-34cf-5a07-b917-7a8bd9ece192'::uuid, 'Algorithmique et programmation'),
    ('d4b320b8-9a93-5dda-9b27-600a8ec20d34'::uuid, 'Algorithmique et programmation'),
    ('3861f096-5925-5e89-9ea8-133faba570d9'::uuid, 'Algorithmique et programmation'),
